text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "2026年华东地区已完成订单销售额城市排名Top3",
      "business_question": "在2026年、华东地区且状态为已完成的订单中，各城市的销售额总和是多少？请按销售额降序排列并取前三名。",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标，提供决策所需的关键数据（城市销售表现排名）。删除此任务将无法回答用户关于特定条件下销售额排名的核心问题。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04",
        "C05"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "华东"
              },
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "order_year"
          }
        },
        {
          "step_id": "S03",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "order_year",
                "operator": "eq",
                "value": 2026
              }
            ]
          }
        },
        {
          "step_id": "S04",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_total"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S05",
          "operation": "sort",
          "params": {
            "field": "sales_total",
            "direction": "desc"
          }
        },
        {
          "step_id": "S06",
          "operation": "top_n",
          "params": {
            "field": "sales_total",
            "direction": "desc",
            "n": 3
          }
        }
      ]
    }
  ]
}
